{ "layoutType": "DigiGoldFaqSlot", "showHeader": "false", "assets": [{ "itemIndex": "1.1", "itemTitle": "Buy Gold", "itemTitleColor": "#000000", "itemNeedsToDisplay": "true", "subItems": [{
"itemtTitle": "What is Tanishq Digital Gold powered by SafeGold?", "itemTitleColor": "#000000", "itemThumbnail": "", "itemContentLink": "", "itemContentType": "", "itemDescription": "Tanishq Digital Gold powered by SafeGold is a safe and transparent platform for buying/selling/exchanging SafeGold offered by Digital Gold India Private Limited (DGIPL) in compliance with all applicable laws and regulations. Tanishq Digital Gold is neither a financial product nor a deposit but a method of purchasing gold for your personal needs. Each time you purchase SafeGold from the Platform, Gold will be purchased on your behalf on the basis of clear funds being made available by you for the transaction. Gold in grams up to 4 decimal places shall be credited to your account.", "itemDescriptionColor": ""
}, {
"itemtTitle": "What is SafeGold", "itemTitleColor": "#000000", "itemThumbnail": "", "itemContentLink": "", "itemContentType": "", "itemDescription": "SafeGold is a product of DGIPL- an institutionally owned company, where the World Gold Council is a minority investor (through World Gold Council (India) Private Limited).", "itemDescriptionColor": ""
}, {
"itemtTitle": "What is the Purity of SafeGold offered through Tanishq Digital Gold", "itemTitleColor": "#000000", "itemThumbnail": "", "itemContentLink": "", "itemContentType": "", "itemDescription": "Tanishq Digital Gold offers SafeGold which is 24 Karat Gold of 995 fineness (99.5% pure) or higher purity which are LBMA good delivery bars sourced by DGIPL from trusted sources.", "itemDescriptionColor": "#000000"
}, {
"itemtTitle": "What is the minimum and maximum amount I can purchase through Tanishq Digital Gold", "itemTitleColor": "#000000", "itemThumbnail": "", "itemContentLink": "", "itemContentType": "", "itemDescription": "The minimum amount of purchase is Rs. 100. There is no maximum amount, subject to the completion of KYC verification for your account.", "itemDescriptionColor": "#000000"
}, {
"itemtTitle": "Is there a minimum lock in period?", "itemTitleColor": "#000000", "itemThumbnail": "", "itemContentLink": "", "itemContentType": "", "itemDescription": "There is no minimum lock in period- you can make a one-time purchase of SafeGold, without being obligated to make any fixed or periodic payments. You can choose to sell any amount of gold at the live sell price starting with minimum of Re. 100/- to maximum of the amount of gold that you own.", "itemDescriptionColor": "#000000"
}, {
"itemtTitle": "Where can I sign up to purchase this?", "itemTitleColor": "#000000", "itemThumbnail": "", "itemContentLink": "", "itemContentType": "", "itemDescription": "You can register through Tanishq App. You will be required to provide your name, mobile number, email address, pin code and PAN to get started. At stores, you can only redeem the SafeGold Balance that is available in your account, but buy and sell is possible only through the Tanishq Digital Gold powered by SafeGold platform.", "itemDescriptionColor": ""
}, {
"itemtTitle": "Can I pay through Post Dated Cheques?", "itemTitleColor": "#000000", "itemThumbnail": "", "itemContentLink": "", "itemContentType": "", "itemDescription": "No, this is an entirely digital product, and hence Post-Dated Cheques (PDCs) are not available as a payment method for this product.", "itemDescriptionColor": "#000000"
}, {
"itemtTitle": "Can I cancel my purchase order to buy SafeGold", "itemTitleColor": "#000000", "itemThumbnail": "", "itemContentLink": "", "itemContentType": "", "itemDescription": "No, you cannot cancel the purchase order of gold once it has been successfully placed on the platform.", "itemDescriptionColor": "#000000"
}, {
"itemtTitle": "Where can I find the invoice for each order?", "itemTitleColor": "#000000", "itemThumbnail": "", "itemContentLink": "", "itemContentType": "", "itemDescription": "If your email address has been provided, an invoice shall be emailed to you as an attachment after each successful transaction. It is also available on the platform, by clicking on the invoice button.", "itemDescriptionColor": ""
}, {
"itemtTitle": "How can I get my holding statement?", "itemTitleColor": "#000000", "itemThumbnail": "", "itemContentLink": "", "itemContentType": "", "itemDescription": "An online statement will be available at all times on the platform.", "itemDescriptionColor": "#000000"
}, {
"itemtTitle": "Can I open a joint account?", "itemTitleColor": "#000000", "itemThumbnail": "", "itemContentLink": "", "itemContentType": "", "itemDescription": "No, you cannot open a joint account for Tanishq Digital Gold powered SafeGold.", "itemDescriptionColor": ""
}, {
"itemtTitle": "Is the gold associated with my accumulations kept in safe custody?", "itemTitleColor": "#000000", "itemThumbnail": "", "itemContentLink": "", "itemContentType": "", "itemDescription": "The gold purchased on your behalf is stored with Brinks, the leading safe keeper of precious metals across the world. The gold is insured, for both storage and transit when being delivered to you. Further, the Security Trustee has a charge on all gold stored in the vault in your favour. This ensures that your gold is protected at all times regardless of any external events.", "itemDescriptionColor": "#000000"
}, {
"itemtTitle": "What is the role of the Security Trustee?", "itemTitleColor": "#000000", "itemThumbnail": "", "itemContentLink": "", "itemContentType": "", "itemDescription": "To provide you SafeGold through the Tanishq Digital Gold Platform, DGIPL has entered into a relationship with IDBI Trusteeship Services Limited to act as a Security Trustee for all digital gold customers. The Security Trustee is entitled to act on your behalf and ensure that your interests are protected. The Security Trustee will have a charge on the gold associated with accumulations held by you.", "itemDescriptionColor": ""
}, {
"itemtTitle": "What will happen to the gold associated with accumulations in my account, in the unlikely event of the SafeGold going into liquidation?", "itemTitleColor": "#000000", "itemThumbnail": "", "itemContentLink": "", "itemContentType": "", "itemDescription": "The gold associated with the accumulations in your account is separate from the other assets of the SafeGold. IDBI Trusteeship Services Limited, an independent trustee, acts for and on your behalf. The gold purchased by DGIPL associated with the accumulations in your accounts is held with the Custodian. When you ask for delivery, the requisite quantity of gold will be removed from the Custodian and delivered to you through a reputed courier service. Since the Security Trustee has a charge over the gold, any unlikely adverse event happening to DGIPL will not affect the gold associated with the accumulations in your account. Further, the title of the gold clearly rests with you and the physical gold stored with the Custodian on account of SafeGold customers is not an asset of SafeGold in any way.", "itemDescriptionColor": "#000000"
}, {
"itemtTitle": "Who will insure the physical vault?", "itemTitleColor": "#000000", "itemThumbnail": "", "itemContentLink": "", "itemContentType": "", "itemDescription": "The secure storage provider (Brinks) has a comprehensive, global insurance policy that includes the insurance cover on your gold stored in their vaults. In addition, DGIPL has an additional insurance policy to cover gold in transit.", "itemDescriptionColor": ""
}, {
"itemtTitle": "What is the maximum period of time for which my gold can be stored with DGIPL?", "itemTitleColor": "#000000", "itemThumbnail": "", "itemContentLink": "", "itemContentType": "", "itemDescription": "You can store your gold with DGIPL for a period of 10 years from the date of purchase. The custody shall be without charge for the first 5 years, and thereafter, will continue to be stored by DGIPL for a nominal fee to cover storage costs. You will be intimated in advance of being charged the fee, and will have the option to sell or request delivery of your gold at all times.", "itemDescriptionColor": "#000000"
}, {
"itemtTitle": "What will happen to my gold if my account is not operational on the platform?", "itemTitleColor": "#000000", "itemThumbnail": "", "itemContentLink": "", "itemContentType": "", "itemDescription": "We will always endeavour to provide you with immediate access to your gold. If, however, your account has been suspended for any reason, we would request you to get in touch with DGIPL customer service centre, in order to reactivate your account and access your gold once again. Customers may get in touch with Tanishq customer service centre as a secondary recourse.", "itemDescriptionColor": ""
}, {
"itemtTitle": "Why is there a difference between SafeGold Rate and Tanishq Ecom rate", "itemTitleColor": "#000000", "itemThumbnail": "", "itemContentLink": "", "itemContentType": "", "itemDescription": "&lt;p&gt;The Gold Rate in SafeGold is the price of Raw Gold that is being traded in the commodity markets which is influenced by various macroeconomic factors including global commodity pricing and Rupee valuation against USD. This Gold rate is not the selling gold rate of a finished product. There are operational costs involved even after raw gold is purchased from the market to convert the gold for amenability to make jewellery and these processing costs are why the Gold Rate of all jewelers (not just Tanishq) differs from the commodity rates.&lt;/br&gt;In addition, the SafeGold rate varies based on the time of the day, as there are intra-day price movements in the commodity market as well.&lt;/p&gt;", "itemDescriptionColor": ""
}] }, { "itemIndex": "1.2", "itemTitle": "Exchange", "itemTitleColor": "#000000", "itemNeedsToDisplay": "true", "subItems": [{
"itemtTitle": "What is the process for converting my SafeGold balance to jewellery?", "itemTitleColor": "#000000", "itemThumbnail": "", "itemContentLink": "", "itemContentType": "", "itemDescription": "&lt;p&gt;You can redeem your SafeGold balance at the SafeGold sell rate for jewellery online or offline, exclusively at Tanishq or CaratLane retail stores or by visiting the appropriate websites, by following the process below:&lt;/br&gt;&lt;/br&gt;Retail Store:&lt;/br&gt;1. You may use the SafeGold balance which is converted to value based on the prevailing SafeGold Sell rate (&ldquo;Redemption Value&rdquo;) towards payment for the jewellery product selected. You may please note that the value of the jewellery to be purchased will be calculated based on the gold rate prevailing at the Tanishq/CaratLane store and making charges and any other charges will be extra (&ldquo;Purchase Value&rdquo;). You may have to pay any differential amount to Tanishq, if the Purchase Value is higher than the Redemption Value.&lt;/br&gt;2. Share your registered mobile number as requested, along with the SafeGold Balance you wish to exchange.&lt;/br&gt;3. You will receive an OTP to confirm the transaction.&lt;/br&gt;4. On verification of the OTP, your SafeGold balance shall be transferred to Tanishq and adjusted against the price of the product calculated based on the prevailing rates at the Tanishq/CaratLane stores.&lt;/br&gt;5. Any discounts or store offers, as may be applicable, will be extended to you.&lt;/br&gt;&lt;/br&gt;Online Channel&lt;/br&gt;1. You may use the SafeGold balance which is converted to value based on the prevailing SafeGold Sell rate (&ldquo;Redemption Value&rdquo;) towards payment for the jewellery product selected. You may please note that the value of the jewellery to be purchased will be calculated based on the gold rate prevailing at the Tanishq/CaratLane website and making charges and any other charges will be extra (&ldquo;Purchase Value&rdquo;). You may have to pay any differential amount to Tanishq, if the Purchase Value is higher than the Redemption Value.&lt;/br&gt;2. Add the product to the cart and place the order&lt;/br&gt;3. Enter the shipping details on the shipment page&lt;/br&gt;4. On the payment page click on the Digital Gold tab&lt;/br&gt;5. You can view the Tanishq Digital Gold balance or other SafeGold balance you are currently holding. Ensure you are using the same mobile number with which you have registered with DGIPL. The amount is calculated as per the SafeGold Sell rate for the grammage you are holding&lt;/br&gt;6. Enter the amount that you wish to redeem. Minimum of Rs. 100.&lt;/br&gt;7. You will receive an OTP on the registered mobile number, enter the OTP.&lt;/br&gt;8. On verification of the OTP, your digital gold balance shall be transferred to Tanishq and adjusted against the price of the product calculated based on the prevailing rates on the Tanishq/Caratlane website . Your digital gold balance and will reduce accordingly.&lt;/br&gt;9. Any discounts or platform offers, as may be applicable, will be extended to you.&lt;/p&gt;", "itemDescriptionColor": ""
}, {
"itemtTitle": "Can I convert my SafeGold balance at any Tanishq store?", "itemTitleColor": "#000000", "itemThumbnail": "", "itemContentLink": "", "itemContentType": "", "itemDescription": "Yes, you can redeem your SafeGold Balance for jewellery at any Tanishq or CaratLane retail store or even through the Tanishq/CaratLane online platforms.", "itemDescriptionColor": "#000000"
}, {
"itemtTitle": "Can I exchange my SafeGold balance at any other jewellery chain?", "itemTitleColor": "#000000", "itemThumbnail": "", "itemContentLink": "", "itemContentType": "", "itemDescription": "If you have purchased from Tanishq Digital Gold powered by SafeGold, you can only exchange it for jewellery at Tanishq or CaratLane stores or online platforms.", "itemDescriptionColor": "#000000"
}, {
"itemtTitle": "Can I exchange the SafeGold I have purchased on other platforms at Tanishq stores as well?", "itemTitleColor": "#000000", "itemThumbnail": "", "itemContentLink": "", "itemContentType": "", "itemDescription": "If you have purchased SafeGold on any other platform, you can exchange it for jewellery at Tanishq/CaratLane stores through the same process as above.", "itemDescriptionColor": ""
}, {
"itemtTitle": "Can I request for physical delivery of my SafeGold?", "itemTitleColor": "#000000", "itemThumbnail": "", "itemContentLink": "", "itemContentType": "", "itemDescription": "You can request physical delivery of gold by visiting www.safegold.com and on as many occasions as you want. You will be required to log in using your registered mobile number, and transferring the gold balance you wish to have delivered, to your SafeGold wallet. Since it is not physically possible to deliver a fractional quantity of gold, the minimum quantity for which the delivery can be made has been kept as low as 0.5 gram and in multiples of 0.5 gram. You can select the quantity and denomination of the gold you wish to withdraw from the available options of coins. Each coin will have different making charges, based on the weight and design of the coin. You must confirm the transaction by paying the additional making and delivery charge. The coins will be delivered at your notified address by a logistics provider arranged by DGIPL, and you will receive a confirmation on your registered mobile number. The delivery can be tracked at any time by logging into the platform. In case of delivery of coin/ bar, the shipment will be mandatorily delivered to your registered address as provided by you and confirmed at the time of delivery request. DGIPL maintains a list of serviceable pin codes, and prior to making any purchase. You will be informed whether their pin code is serviceable by DGIPL.", "itemDescriptionColor": "#000000"
}, {
"itemtTitle": "Can I change/cancel my delivery order?", "itemTitleColor": "#000000", "itemThumbnail": "", "itemContentLink": "", "itemContentType": "", "itemDescription": "&lt;p&gt;Once you place a delivery request, you must accept the delivery made to you. It cannot be changed, cancelled or delivered at a later point in time.&lt;/br&gt;Please visit www.safegold.com for further details on the delivery of gold process.&lt;/p&gt;", "itemDescriptionColor": ""
}, {
"itemtTitle": "Are there any charges for delivery of gold?", "itemTitleColor": "#000000", "itemThumbnail": "", "itemContentLink": "", "itemContentType": "", "itemDescription": "Yes, you will be required to pay the minting/ making charges, delivery charges and applicable taxes. All coins are independently assayed to certify purity and delivered in tamper proof packaging. Charges may be viewed on www.safegold.com.", "itemDescriptionColor": "#000000"
}, {
"itemtTitle": "What happens to my gold if I deactivate or close my account with SafeGold balance present?", "itemTitleColor": "#000000", "itemThumbnail": "", "itemContentLink": "", "itemContentType": "", "itemDescription": "At the time of deactivation, you will be offered the option to withdraw your SafeGold balance or request for delivery of your gold.", "itemDescriptionColor": "#000000"
}] }, { "itemIndex": "1.3", "itemTitle": "Sell Gold", "itemTitleColor": "#000000", "itemNeedsToDisplay": "true", "subItems": [{
"itemtTitle": "How do I sell my gold?", "itemTitleColor": "#000000", "itemThumbnail": "", "itemContentLink": "", "itemContentType": "", "itemDescription": "&lt;p&gt;Tanishq Digital Gold Platform provides a live sell price quote. You can choose to sell any amount starting with a minimum of Re 1 to a maximum of the amount of SafeGold that you own. The sell quote may be temporarily unavailable in the unlikely event of a disruption in the bullion market.&lt;/br&gt;To sell your gold, you can enter the amount in rupees or gold in grams. You will be required to fill in the bank details, which will be verified. Upon verification and the sell transaction being successful, the sale proceeds will be credited to your verified bank account by DGIPL within 2-3 working days.&lt;/p&gt;", "itemDescriptionColor": "#000000"
}, {
"itemtTitle": "Where do I get the proceeds when I sell my gold?", "itemTitleColor": "#000000", "itemThumbnail": "", "itemContentLink": "", "itemContentType": "", "itemDescription": "When you sell your gold, you&rsquo;ll receive funds against it in a verified bank account in your own name. You can add your account details prior to the sale, which will be verified by DGIPL. Once the verification is complete, you&rsquo;ll receive the proceeds post the sale of your gold, within 2-3 working days. If the sell transaction has been made on Friday/Saturday or Sunday, then you will receive your sales proceeds by Tuesday of the following week.", "itemDescriptionColor": ""
}, {
"itemtTitle": "What happens if the sales proceeds are not credited to me within 4 working days?", "itemTitleColor": "#000000", "itemThumbnail": "", "itemContentLink": "", "itemContentType": "", "itemDescription": "If the sales proceeds have not been received within 4 working days of the transaction, please email our customer service team at tanishqdigitalgold@titan.co.in with your related transaction details, and we shall resolve your issue.", "itemDescriptionColor": "#000000"
}, {
"itemtTitle": "I&rsquo;m facing issues with bank account verification, what should I do?", "itemTitleColor": "#000000", "itemThumbnail": "", "itemContentLink": "", "itemContentType": "", "itemDescription": "In case you are facing any issues with uploading your proof of Bank account documents or completing the verification, please reach out to our support team with a screenshot of the issue on tanishqdigitalgold@titan.co.in", "itemDescriptionColor": ""
}, {
"itemtTitle": "Why is the SafeGold Sell Price different from the SafeGold Buy Price?", "itemTitleColor": "#000000", "itemThumbnail": "", "itemContentLink": "", "itemContentType": "", "itemDescription": "&lt;p&gt;DGIPL offers international grade bullion from institutional suppliers and sells this to consumers. When customers sell the gold back, the gold is sold back to institutional participants in the wholesale bullion market, where the buyback rate is lower than the selling rate &ndash; this is referred to as the buy-sell spread.&lt;/br&gt;In addition to the buy-sell spread in the commercial bullion market, GST is added to the buy price, but it is not levied on any sell transactions. Further, there are charges incurred on the payment gateway, trustee, insurance and custodian fees which also contribute to the difference in buy and sell price.&lt;/p&gt;", "itemDescriptionColor": "#000000"
}, {
"itemtTitle": "Can I cancel my sell order/request of gold sell?", "itemTitleColor": "#000000", "itemThumbnail": "", "itemContentLink": "", "itemContentType": "", "itemDescription": "No, you cannot cancel the order once it has been successfully placed on the platform.", "itemDescriptionColor": ""
}, {
"itemtTitle": "What happens to the SafeGold Balance in the event of a Customer&rsquo;s death?", "itemTitleColor": "#000000", "itemThumbnail": "", "itemContentLink": "", "itemContentType": "", "itemDescription": "In the event of your death, as per the process specifically allowed by DGIPL , and subject to the required due diligence, the title to your gold lying in the vault and your account shall transfer to your legal heir, subject to legal heirs providing valid documents to the satisfaction of DGIPL to prove their heirship.", "itemDescriptionColor": "#000000"
}] }, { "itemIndex": "1.4", "itemTitle": "Customer Support", "itemTitleColor": "#000000", "itemNeedsToDisplay": "true", "subItems": [{
"itemtTitle": "I have some queries regarding my gold account, how can I get in touch?", "itemTitleColor": "#000000", "itemThumbnail": "", "itemContentLink": "", "itemContentType": "", "itemDescription": "Please raise a ticket or get in touch with Tanishq&rsquo;s customer service centre, through tanishqdigitalgold@titan.co.in. Tanishq is available to provide the first level of support and SafeGold shall be available to address any questions/issues that may be escalated.", "itemDescriptionColor": ""
}, {
"itemtTitle": "Is there any regulator or Grievance redressal mechanism?", "itemTitleColor": "#000000", "itemThumbnail": "", "itemContentLink": "", "itemContentType": "", "itemDescription": "SafeGold is neither a Collective Investment Scheme nor a Deposit. Thus, does not fall under the purview of SEBI or RBI, and there is no regulator for this product offering. To ensure that your interest is of foremost importance, a Security Trustee has been appointed for SafeGold. For any grievances specifically in relation to your gold purchase and related transactions, you can approach the Security Trustee.", "itemDescriptionColor": ""
}] }] }

