  },
  "loyaltyText6" : "<h4>Titan &amp; Partner Brands</h4><p>Unlock Exciting Benifits</p><p>from Titan &amp; Partners!</p>",
  "image1mbl" : {
    "path" : "/images/loyalty-programs-page/titan-encircle-mbl.png",
    "focal_point" : {
      "x" : 0.5,
      "y" : 0.5
    },
    "meta_data" : {
      "height" : 340,
      "width" : 344
    }
  },
  "loyaltyText5" : "<h4>Refferal Rewards</h4><p>Get Benifits by referring your</p><p>loved ones to Titan brands</p>",
  "loyaltyText4" : "<h4>Offers For You</h4><p>Exclusive offers avail at</p><p>any of the Titan stores</p>",
  "loyaltyText3" : "<p>The NeuCoins earned are valid for 12 months</p><p>from the date of last transaction.</p>",
  "loyaltyText9" : "<h4>Eye Checkup &amp; Servicing</h4><p>Free Eyewear servicing &amp; 6-month</p><p>Contact Lens Refill Reminder!</p>",
  "loyaltyText8" : "<h4>Free Cleaning</h4><p>Free cleaning service for</p><p>your jewellery &amp; watches.</p>",
  "loyaltyText7" : "<h4>Exclusive Preview</h4><p>Be the first to explore our</p><p>new products</p>",
  "image5" : {
    "path" : "/images/loyalty-programs-page/loyalty-image2.png",
    "focal_point" : {
      "x" : 0.5,
      "y" : 0.5
    },
    "meta_data" : {
      "height" : 120,
      "width" : 120
    }
  },
  "image6" : {
    "path" : "/images/loyalty-programs-page/loyalty-image3.png",
    "focal_point" : {
      "x" : 0.5,
      "y" : 0.5
    },
    "meta_data" : {
      "height" : 120,
      "width" : 120
    }
  },
  "image3" : {
