custom-attributes.custom-attribute:
{
	"id": "help-faqs",
	"name": "Help & FAQs",
	"c_categories": [
		{
			"id": "order-delivery",
			"title": "Order Delivery And Shipping",
			"questions": [
				{
					"question": "How can I know the status of my order?",
					"answer": "All users have the option to track their orders by clicking on Track Order. You need to enter the email address used while placing the order and the order number to track the order. Registered users can sign in and track their orders from the order history section on the account page."
				},
				{
					"question": "What happens if my order is lost in transit?",
					"answer": "In the unlikely event that an order gets lost during transit, we wait for 15 days to track your lost order and if we are still unsuccessful, then we process your refund through the payment mode that you had opted for at the time of placing the order."
				},
				{
					"question": "Where do you deliver within India?",
					"answer": "Currently, we deliver to selected cities within India. Please check if we deliver to your PIN code/city by entering it on the product page/shopping/cart checkout page. If there is no courier service available in your area/city, we apologize for the inconvenience caused."
				},
				{
					"question": "I live outside India. Can I order something to be delivered in India?",
					"answer": "Yes."
				},
				{
					"question": "Do I need to pay shipping/delivery charges?",
					"answer": "There are no shipping/delivery charges within India. We charge $50 extra as shipping and handling charges for international destinations for all jewellery products. All products are dispatched on a \"Delivery Duty Unpaid\" (DDU) basis."
				},
				{
					"question": "How soon will I receive my order?",
					"answer": "The time taken for delivery tends to vary according to the destination; however, we make our best efforts to ensure that the domestic order is delivered within 2\u20137 working days of you placing the order. For international orders, please see the Time to Deliver section under the Shipping Policy."
				}
			]
		},
		{
			"id": "my-account",
			"title": "My Account",
			"questions": [
				{
					"question": "Do I need to register to be able to shop at www.beyon.co.in?",
					"answer": "We strongly recommend that you register on www.beyon.co.in as it makes your checkout faster, allows you to track your order, saves products that interest you to a wishlist and provides a better shopping experience."
				},
				{
					"question": "I don't remember my password. What do I do?",
					"answer": "You can enter your e-mail address and click on the \"forgot password\" link in the login page and we will e-mail you a system-generated change password link to your registered email address. However, you should set a new password."
				},
				{
					"question": "Can I edit my personal details?",
					"answer": "You can edit your personal details by accessing the \"edit details\" section in the Personal Information section."
				},
				{
					"question": "Can I have multiple accounts linked to the same email ID?",
					"answer": "No, you can have only one account linked to a single email address."
				},
				{
					"question": "Are the personal details that I have shared with you secure?",
					"answer": "We understand that your privacy is important to you and we respect that. We ensure you that we will maintain complete confidentiality of the details that you have shared with us. You can refer to our Privacy Policy for more information."
				}
			]
		},
		{
			"id": "payment",
			"title": "Payment",
			"questions": [
				{
					"question": "What are the payment options available?",
					"answer": "<b>Domestic Orders:</b> Payments can be made through credit cards, debit cards, international cards, net banking or cash on delivery. Payments on www.beyon.co.in will be accepted only in INR for domestic orders. In case of international credit cards, the transaction amount will be converted to INR before the payment is accepted.<br><br><b>International Orders:</b> Payments for International Orders are accepted through PayPal Payment gateway either by your PayPal account or by using International credit/debit cards only. Payment will be accepted only in US Dollars. Indian issued cards will not be accepted for international orders."
				},
				{
					"question": "Which credit cards are accepted for domestic and international payments?",
					"answer": "We accept Visa | MasterCard | AMEX | Diners | JCB for domestic and international payments."
				},
				{
					"question": "Which domestic debit cards are accepted?",
					"answer": "<b>Debit Cards \u2013 Visa Gateway:</b> Axis Bank, Bank of Baroda, Barclays Bank, Canara Bank, City Union Bank, Corporation Bank, Dena Bank, Deutsche Bank, Federal Bank, HDFC Bank, ICICI Bank, IDBI Bank, Indian Overseas Bank, IndusInd Bank, Kotak Bank, Karur Vyasa Bank, Laxmi Vilas Bank, Standard Chartered Bank, State Bank Of India, Syndicate Bank, Union Bank of India<br><br><b>Debit Cards \u2013 MasterCard:</b> Bank Of India, Canara Bank, Central Bank of India, Citibank, Corporation Bank, Federal Bank, HDFC Bank, ICICI Bank, IDBI Bank, Indian Bank, Punjab National Bank, Standard Chartered Bank, State Bank Of India, The Royal Bank of Scotland, Union Bank of India, YES Bank<br><br><b>Maestro Cards:</b> Citibank, State Bank of India"
				},
				{
					"question": "Accepted domestic banks for payment through net banking?",
					"answer": "<b>Internet Banking \u2013 Retail:</b> Allahabad Bank, Andhra Bank, Axis Bank, Bank of Bahrain and Kuwait, Bank of Baroda, Bank of India, Bank of Maharashtra, Canara Bank, Central Bank of India, City Union Bank, Corporation Bank, Deutsche Bank, Dhanlakshmi Bank, Federal Bank, HDFC Bank, ICICI Bank, IDBI Bank, Indian Bank, Indian Overseas Bank, IndusInd Bank, ING Vysya Bank, Jammu and Kashmir Bank, Karnataka Bank, Karur Vysya Bank, Kotak Mahindra Bank, Yes Bank, Vijaya Bank, Laxmi Vilas Bank, Oriental Bank of Commerce, Punjab National Bank, South Indian Bank, State Bank of India, Syndicate Bank, Tamilnad Mercantile Bank, UCO Bank, Union Bank of India, United Bank of India<br><br><b>Internet Banking \u2013 Corporate:</b> Karur Vysya Bank, Lakshmi Vilas Bank, Punjab National Bank, Bank of Maharashtra, Bank of Baroda, Bank of India, State Bank of India, Union Bank of India"
				},
				{
					"question": "Is Cash on Delivery available?",
					"answer": "No."
				}
			]
		},
		{
			"id": "returns-exchanges",
			"title": "Returns And Exchanges",
			"questions": [
				{
					"question": "How can I cancel my order?",
					"answer": "Orders once placed can only be cancelled prior to shipment. Please refer to our cancellation policy for more details."
				},
				{
					"question": "In case I change my mind about the size picked up, can I replace the order?",
					"answer": "Yes, it is possible to return the unused product and order a replacement. Please refer to the Return Policy for details. Please note that returns/replacements are not applicable for International Orders, although there are a few exceptions."
				},
				{
					"question": "What do I do if I receive the wrong product?",
					"answer": "You can call us at 1800-266-0123 and write to ecomsupport@titan.co.in to report the incident and cancel the order. If you want to return the product, please do not use it. We will arrange for the pick-up of the unused item from the provided address through our logistic partner and arrange for the refund."
				},
				{
					"question": "The product that I received was damaged and I want to return it. What do I do?",
					"answer": "In the unlikely event that the product delivered is in damaged condition, you can return the product unused and in the same condition as you received it, in its original packaging, along with the invoice for a refund. Call us at 1800-266-0123 or write to ecomsupport@titan.co.in within 30 days of receipt of the product to report the incident."
				},
				{
					"question": "What is the return policy?",
					"answer": "You can return the product unused and in the same condition as you received it, in its original packaging, along with the invoice for a refund. We will arrange for the order to be collected from the provided address through our logistic partner and returned to us. We shall process the refund only after the receipt of the product at our location in unused condition and in its original packaging along with its original tags and invoice."
				},
				{
					"question": "Do I need to pay for the return shipment if I return my order?",
					"answer": "We will arrange for the return shipment to be collected and you do not need to make any payment for the courier. For International Orders, please check the International Order section under Return policy."
				},
				{
					"question": "How do I return my order?",
					"answer": "The order can be returned within 15 days from the date you receive the product. If you wish to return the product, you need to call customer care at 1800-266-0123 or email ecomsupport@titan.co.in stating that you want to return the product.\n\na) Pack your order in original packaging and mention your name, order number and mobile number.\nb) Enclose the original invoice, guarantee/warranty card & other tag, if any.\nc) Our logistic partner will pick up the package from you.\nd) Post inspection, only after we get a go-ahead from the QA team, the refund process will be initiated.\n\nPlease note that returns are not accepted for coins, silver products, and nose pins."
				},
				{
					"question": "Can I exchange the Beyon product purchased online at any Beyon House of Titan Store?",
					"answer": "\u2022 Laboratory-grown diamonds used in BEYON jewellery are not eligible for exchange or buyback.\n\u2022 The Gold component of BEYON jewellery is eligible for exchange at prevailing gold rates, subject to verification and applicable policies.\n\u2022 Exchanges are permitted only at authorized BEYON retail stores for products bought online or at BEYON stores.\n\u2022 The BEYON exchange program may be modified or withdrawn at Titan's discretion without notice."
				}
			]
		},
		{
			"id": "international-shipping",
			"title": "International Shipping",
			"questions": [
				{
					"question": "Is International Shipping available for Jewellery?",
					"answer": "Yes, we do undertake and fulfil orders for International Destinations."
				},
				{
					"question": "Which are the international shipping destinations covered?",
					"answer": "Australia, Bahrain, Canada, Germany, India, Italy, Kenya, Kuwait, Malaysia, Netherlands, New Zealand, Oman, Portugal, Qatar, Romania, Saudi Arabia, Singapore, South Africa, Spain, United Arab Emirates, United Kingdom."
				},
				{
					"question": "What is the minimum order value for an International Order?",
					"answer": "For all international orders, your cart value should be a minimum of $50 and a maximum of $10,000. This is exclusive of all shipping and handling charges."
				},
				{
					"question": "Which mode of payment option is available for international orders?",
					"answer": "Payments are accepted through the PayPal Payment gateway either by your PayPal account or by using International credit/debit cards only. Payment will be received only in USD. Please note that cards (credit or debit) issued in India will not be accepted for any international orders."
				},
				{
					"question": "Who is the shipping partner?",
					"answer": "Our international shipping partner is UPS."
				},
				{
					"question": "In how many days will I receive my international order?",
					"answer": "You will receive your order within 2\u20133 weeks after the confirmation of the order. An email confirmation will be sent to you once your product is dispatched from our warehouse. Our logistic partner will get in touch with you once your product reaches its destination."
				},
				{
					"question": "Shipping charges",
					"answer": "We charge $50 extra as shipping and handling charges for international destinations for all jewellery products. All products are dispatched on a \"Delivery Duty Unpaid\" (DDU) basis."
				},
				{
					"question": "Are returns or exchanges accepted?",
					"answer": "Currently, we do not accept any returns or exchanges of our products in case of international orders."
				}
			]
		}
	]
}

